json.content:
:root {
  --cream: #F6EEE1;
  --paper: #FFFBF4;
  --brown: #3B2A20;
  --soft: #6E5A4C;
  --accent: #9C5B2E;
  --line: #E4D6C2;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--brown);
  font-family: Georgia, 'Iowan Old Style', 'Palatino Linotype', serif;
  font-size: 18px;
  line-height: 1.55;
}

.top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 960px;
  margin: 0 auto;
  padding: 20px 24px;
}

.mark { margin: 0; font-weight: 700; letter-spacing: 0.02em; }

nav a {
  color: var(--brown);
  margin-left: 18px;
  text-decoration: none;
  border-bottom: 1px solid transparent;
}

nav a:hover { border-bottom-color: var(--accent); }

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 24px 48px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
}

.hero { grid-column: 1 / -1; padding: 48px 0 24px; }

.hero h1 {
  font-size: clamp(40px, 7vw, 72px);
  line-height: 1.02;
  margin: 0 0 16px;
  letter-spacing: -0.02em;
}

.lead { font-size: 21px; max-width: 34em; color: var(--soft); margin: 0; }

.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 24px;
}

.card h2 { margin: 0 0 12px; font-size: 24px; }

dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; margin: 0; }
dt { color: var(--soft); }
dd { margin: 0; font-variant-numeric: tabular-nums; }

.menu { list-style: none; margin: 0; padding: 0; }

.menu li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px dotted var(--line);
}

.price { font-variant-numeric: tabular-nums; font-weight: 700; }

.note { color: var(--soft); font-size: 16px; margin: 12px 0 0; }

.call {
  display: inline-block;
  margin-top: 8px;
  padding: 12px 18px;
  border-radius: 999px;
  background: var(--brown);
  color: var(--paper);
  text-decoration: none;
}

footer {
  max-width: 960px;
  margin: 0 auto;
  padding: 24px;
  border-top: 1px solid var(--line);
  color: var(--soft);
  font-size: 16px;
}

footer p { margin: 4px 0; }

@media (max-width: 600px) {
  .top { flex-direction: column; align-items: flex-start; gap: 8px; }
  nav a { margin: 0 16px 0 0; }
}

